<script setup>
import {computed,ref} from 'vue';import {brushPresets,cdtItems,auditQuote} from '../engines/sonicBrushAndCdtAuditorEngine.js';
const emit=defineEmits(['save']);const brush=ref(brushPresets[0]);const activeZone=ref(0);const codes=ref([{code:'D0150',price:120},{code:'D2391',price:240},{code:'D1110',price:130}]);const result=computed(()=>auditQuote(codes.value));const add=()=>codes.value.push({code:'D2740',price:1200});
</script>
<template><section class="module-card glass"><div class="module-head"><div><div class="eyebrow">05 / Brushing habits & treatment estimate review</div><h2>Brush coach & quote review</h2><p>Practice gentle brushing coverage and compare entered prices against illustrative sample values. This is not a calibrated force sensor or a determination of dental necessity.</p></div><span class="badge">SIMULATOR · SAMPLE VALUES</span></div><div class="two-col"><div><div class="inner"><h3>Pressure practice</h3><div class="pressure-gauge"><div class="gauge-track"><div class="gauge-fill" :style="{width:Math.min(100,brush.grams/4)+'%'}"></div><div class="gauge-marker"></div></div><div class="gauge-read"><b>{{brush.grams}} g</b><span>{{brush.grams>200?'Try a lighter touch':'Gentle pressure scenario'}}</span></div></div><div class="preset-list" style="margin-top:15px"><button v-for="p in brushPresets" :key="p.name" class="preset" :class="{active:brush.name===p.name}" @click="brush=p">{{p.name}} · {{p.grams}}g</button></div><p class="footnote">Force is preset-only: phone microphones cannot accurately measure bristle force.</p></div><div class="inner" style="margin-top:12px"><h3>2-minute coverage coach · {{Math.min(4,Math.floor(activeZone/4)+1)}} / 4 quadrant</h3><div class="coverage-grid"><button v-for="i in 16" :key="i" class="coverage-zone" :class="{done:i-1<activeZone}" @click="activeZone=i">{{i<=4?'B':i<=8?'L':i<=12?'O':'M'}}<small>{{i}}</small></button></div><div class="control-row"><span class="small">Zone timer</span><b>{{Math.max(0,120-activeZone*7.5).toFixed(0)}} sec left</b></div><button class="action" @click="activeZone=(activeZone+1)%16">Next surface →</button></div></div><div><div class="inner"><div class="control-row"><h3 style="margin:0">Quote lines</h3><button class="action secondary" @click="add">+ Add crown sample</button></div><div class="quote-list"><div v-for="(line,i) in codes" :key="i" class="quote-row"><select v-model="line.code" class="select"><option v-for="item in cdtItems" :key="item.code" :value="item.code">{{item.code}} · {{item.name}}</option></select><input class="text-input" type="number" min="0" v-model.number="line.price" aria-label="Quoted price"></div></div><div class="metric-grid"><div class="metric"><span>Entered total</span><b>{{result.total.toLocaleString()}}</b></div><div class="metric"><span>Line items</span><b>{{codes.length}}</b></div><div class="metric"><span>Currency</span><b>Set locally</b></div></div><div class="scroll"><div v-for="row in result.rows" :key="row.code+row.price" class="control-row"><span class="small">{{row.code}} · {{row.flag}}</span><b>{{row.price}}</b></div></div><p class="footnote">{{result.disclaimer}} Values are generic examples, not Meru/Kenya regional fee data or a recommendation to accept/refuse care.</p><button class="action" @click="emit('save',{module:'brush_cdt_audits',lines:codes,total:result.total,reference:result.reference})">Save audit draft</button></div><div class="notice" style="margin-top:12px">For pressure injury, bleeding gums, severe pain, swelling, or facial trauma, seek prompt professional care. For estimates, ask your dentist to explain alternatives and clinical findings.</div></div></div></section></template>
<style scoped>.pressure-gauge{padding:20px 8px}.gauge-track{height:12px;position:relative;border-radius:99px;background:linear-gradient(90deg,#54cea566 0 40%,#ebc35a66 40% 55%,#e76f7566 55%);overflow:visible}.gauge-fill{height:100%;position:absolute;left:0;top:0;background:linear-gradient(90deg,#74ead2,#d2bd70);border-radius:inherit}.gauge-marker{position:absolute;left:50%;top:-5px;height:22px;width:2px;background:white}.gauge-read{display:flex;justify-content:space-between;margin-top:12px;font-size:10px;color:#aab7bc}.gauge-read b{font:17px 'DM Mono';color:#e8fff8}.coverage-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin:14px 0}.coverage-zone{height:48px;border:1px solid var(--line);background:#ffffff06;border-radius:10px;color:#9daeb4;font:10px 'DM Mono'}.coverage-zone.done{border-color:#72e4cd;background:#60d8c51b;color:#cffff0}.coverage-zone small{display:block;opacity:.55;font-size:8px}.quote-list{display:grid;gap:7px;margin-top:10px}.quote-row{display:grid;grid-template-columns:1fr 86px;gap:7px}.quote-row .select{min-width:0;font-size:9px}</style>
